import sys
import json
from typing import Any, Dict, List

result: List[str] = []


def get_unique_tags(access_points: List[Dict[str, Any]]) -> List[str]:
    seen = set()
    unique_tags = []

    for ap in access_points:
        tags = ap.get("tags", [])
        if isinstance(tags, list):
            for tag in tags:
                if isinstance(tag, str) and tag not in seen:
                    seen.add(tag)
                    unique_tags.append(tag)

    return unique_tags


if len(sys.argv) < 2:
    raise ValueError("Please pass the JSON array as the first argument.")

input_data = json.loads(sys.argv[1])
result = get_unique_tags(input_data)

import sys
import json
from typing import Any, Dict, List

output = ""


def to_markdown_table(rows: List[Dict[str, Any]]) -> str:
    if not isinstance(rows, list):
        raise ValueError("Input must be a JSON array.")

    if not rows:
        return ""

    columns = []
    seen = set()

    for row in rows:
        if not isinstance(row, dict):
            raise ValueError("Each item in the array must be an object.")
        for key in row.keys():
            if key not in seen:
                seen.add(key)
                columns.append(key)

    def format_value(value: Any) -> str:
        if value is None:
            return ""
        if isinstance(value, (dict, list)):
            text = json.dumps(value, ensure_ascii=False)
        else:
            text = str(value)
        return text.replace("|", "\\|").replace("\n", "<br>")

    header = "| " + " | ".join(columns) + " |"
    separator = "| " + " | ".join(["---"] * len(columns)) + " |"
    body = [
        "| " + " | ".join(format_value(row.get(column, "")) for column in columns) + " |"
        for row in rows
    ]

    return "\n".join([header, separator] + body)


if len(sys.argv) < 2:
    raise ValueError("Please pass the JSON array as the first argument.")

input_data = json.loads(sys.argv[1])
output = to_markdown_table(input_data)
